window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f2d84eaa2ec0bde4"]={"versions": [{"id": "FIG-f2d84eaa2ec0bde4", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition einer AUTOSAR-Port-Schnittstelle im Kontext des Diagnostic Communication Manager (DCM, SWS DCM). Das Diagramm spezifiziert die Schnittstellendefinition für Reset-Dienste (<code>ResetService</code>) innerhalb des AUTOSAR Classic Platform Schichtenmodells für die Diagnosekommunikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert das Interface <code>ResetService</code> (Stereotyp <code>«interface»</code>) mit der Operation:</p>\n<ul class=\"fig-list\"><li><code>EcuReset(return :Std_ReturnType, ResetType :uint8, ErrorCode :Dcm_NegativeResponseCodeType*)</code>\n</li></ul>\n<p class=\"fig-p\">Parameter und Datentypen:</p>\n<ul class=\"fig-list\"><li>Rückgabewert: <code>Std_ReturnType</code>\n</li><li>Eingabeparameter <code>ResetType</code>: Datentyp <code>uint8</code>\n</li><li>Ausgabeparameter bzw. Zeiger <code>ErrorCode</code>: Datentyp <code>Dcm_NegativeResponseCodeType*</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Klassendiagramm ohne explizite Modellierung von Zuständen oder Sequenzen. Die Operation <code>EcuReset</code> repräsentiert einen synchronen bzw. asynchronen Client-Server-Aufruf zwischen dem DCM und einer angebundenen Software-Komponente / BSW-Komponente zur Ausführung eines ECU-Resets inklusive Rückmeldung eines Fehlercodes (<code>ErrorCode</code>) bei Fehlschlag.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Schnittstellendefinition für Client-Server-Ports vom Typ <code>ResetService</code>. Implementierende Software-Komponenten müssen die Operation <code>EcuReset</code> mit exakt der angegebenen Signatur bereitstellen bzw. aufrufen: Übergabe des Reset-Subfunktions-Identifikators (<code>ResetType</code>), Rückgabe des Funktionsstatus (<code>Std_ReturnType</code>) und Bereitstellung des Fehlerspeichers über den Zeiger <code>ErrorCode</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-361e52d7af06d715", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition einer AUTOSAR-Port-Schnittstelle im Kontext des Diagnostic Communication Manager (DCM, SWS DCM). Das Diagramm spezifiziert die Schnittstellendefinition für Reset-Dienste (<code>ResetService</code>) innerhalb des AUTOSAR Classic Platform Schichtenmodells für die Diagnosekommunikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert das Interface <code>ResetService</code> (Stereotyp <code>«interface»</code>) mit der Operation:</p>\n<ul class=\"fig-list\"><li><code>EcuReset(return :Std_ReturnType, ResetType :uint8, ErrorCode :Dcm_NegativeResponseCodeType*)</code>\n</li></ul>\n<p class=\"fig-p\">Parameter und Datentypen:</p>\n<ul class=\"fig-list\"><li>Rückgabewert: <code>Std_ReturnType</code>\n</li><li>Eingabeparameter <code>ResetType</code>: Datentyp <code>uint8</code>\n</li><li>Ausgabeparameter bzw. Zeiger <code>ErrorCode</code>: Datentyp <code>Dcm_NegativeResponseCodeType*</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Klassendiagramm ohne explizite Modellierung von Zuständen oder Sequenzen. Die Operation <code>EcuReset</code> repräsentiert einen synchronen bzw. asynchronen Client-Server-Aufruf zwischen dem DCM und einer angebundenen Software-Komponente / BSW-Komponente zur Ausführung eines ECU-Resets inklusive Rückmeldung eines Fehlercodes (<code>ErrorCode</code>) bei Fehlschlag.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Schnittstellendefinition für Client-Server-Ports vom Typ <code>ResetService</code>. Implementierende Software-Komponenten müssen die Operation <code>EcuReset</code> mit exakt der angegebenen Signatur bereitstellen bzw. aufrufen: Übergabe des Reset-Subfunktions-Identifikators (<code>ResetType</code>), Rückgabe des Funktionsstatus (<code>Std_ReturnType</code>) und Bereitstellung des Fehlerspeichers über den Zeiger <code>ErrorCode</code>.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-f2d84eaa2ec0bde4", "to": "FIG-361e52d7af06d715", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Der umgebende UML-Paket-/Klassendiagramm-Rahmen <code>class ResetService</code> wurde entfernt; die Schnittstelle steht nun ohne Diagrammrahmen da.\n</li><li>Die Typografie des Schnittstellennamens <code>ResetService</code> wurde von fett-kursiv auf Standard-Schriftschnitt gesetzt.\n</li><li>Der Schlagschatten des Schnittstellen-Kastens wurde entfernt.\n</li></ul>"}]};
